-- إعادة تفعيل حماية الإغراق
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers enable trigger aq_rate_limit_service_providers;
  end if;
end $$;

-- للتأكد: عدد الشركات في كل قسم وإمارة
select category, emirate, count(*) from public.service_providers where is_active group by 1, 2 order by 1, 3 desc;

-- ============================================================================
-- تعبئة دليل الخدمات بشركات حقيقية (من مواقعها الرسمية ومصادر موثوقة).
-- تُدرج مفعّلة وغير «موثّقة الرخصة» — وثّقي الرخصة من صفحة الإدارة بعد التحقق.
-- آمن لو أُعيد تشغيله: لا يكرّر شركة موجودة بنفس القسم والإمارة والاسم.
-- يُنفَّذ بعد service_providers.sql و service_categories_v2.sql من Supabase → SQL Editor.
-- ============================================================================
-- تعطيل مؤقت لحماية الإغراق أثناء الإدراج الجماعي من SQL Editor (تُعاد في آخر الملف)
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers disable trigger aq_rate_limit_service_providers;
  end if;
end $$;
alter table public.service_providers add column if not exists founded_year int;
alter table public.service_providers add column if not exists source_url text;
alter table public.service_providers add column if not exists about text;
alter table public.service_providers add column if not exists address text;
alter table public.service_providers add column if not exists map_url text;
alter table public.service_providers add column if not exists portfolio text[] not null default '{}';
alter table public.service_providers add column if not exists team_info text;

insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'cleaning', 'Justlife', 'Justlife', 'دبي', null, null, 'https://www.justlife.com', null, 'منصة لخدمات تنظيف المنازل بالساعة والتنظيف العميق وتنظيف الكنب والسجاد في الإمارات.', 'https://www.justlife.com/en-AE/house-cleaning-dubai', 'تقدم جاست لايف تنظيف المنازل بالساعة أو لمرة واحدة أو أسبوعياً، إضافة إلى التنظيف العميق وتنظيف ما قبل الانتقال وبعده. وتشمل خدماتها تنظيف الكنب والمراتب والستائر والسجاد وخدمات منزلية أخرى. وتعمل في دبي وأبوظبي والشارقة وعجمان وكذلك جدة والرياض.', 'https://cdn.justlife.com/prod/assets/static/themed/svgs/jl-logo.svg?theme=default.c30210bf', null, null, null, array['تنظيف المنازل بالساعة', 'التنظيف العميق', 'تنظيف الانتقال (دخول/خروج)', 'تنظيف الكنب والمراتب والسجاد', 'تنظيف الفلل']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Justlife'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'cleaning', 'The Maid Company', 'The Maid Company', 'دبي', null, '+971504569200', 'https://www.themaidcompany.ae', null, 'شركة تقدم خدمات العاملات بالساعة والإقامة الداخلية والخارجية للتنظيف في دبي والشارقة.', 'https://www.themaidcompany.ae/about/About-us', 'تقدم ذا ميد كومباني خدمات عاملات التنظيف بالساعة والمقيمات وغير المقيمات مع توفير المواصلات ومواعيد مرنة في دبي والشارقة. وتذكر أن مؤسستها هي شركة ديربي للتسويق ذ.م.م، وأنها خدمت أكثر من 5000 عميل.', 'https://www.themaidcompany.ae/Content/images/4tmc.png', 'contact@themaidcompany.ae', null, null, array['عاملات تنظيف بالساعة', 'عاملات مقيمات', 'عاملات غير مقيمات', 'خدمة كفالة العاملة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('The Maid Company'));
