select 'cleaning', 'Dusty Might Building Cleaning Services LLC', 'Dusty Might Building Cleaning Services LLC', 'دبي', 'القوز الصناعية 4', '+97143415955', 'https://www.dmmaids.ae', 2013, 'شركة تنظيف مبانٍ ومنازل في دبي تقدم عاملات بالساعة وتنظيف الانتقال والتنظيف العميق للأثاث.', 'https://www.dmmaids.ae/', 'تعمل داستي مايت لخدمات تنظيف المباني منذ 2013 في دبي. وتقدم تنظيف المنازل والفلل والمكاتب والمحلات والمباني، وتنظيف النوافذ والتنظيف العميق للأثاث وتنظيف الانتقال، بنظام الساعة أو الأسبوع أو الشهر.', 'https://www.dmmaids.ae/images/cleaningservicesdubai.png', 'dustymight@gmail.com', 'منطقة القوز الصناعية 4، دبي', null, array['تنظيف المنازل والفلل', 'تنظيف المكاتب والمباني', 'تنظيف الانتقال', 'التنظيف العميق للأثاث', 'مساعدات الحفلات']::text[], null, true
