select 'cleaning', 'Grace Quest Cleaning Services (Dubai Housekeeping)', 'Grace Quest Cleaning Services (Dubai Housekeeping)', 'دبي', 'شارع الشيخ زايد', '+97142631976', 'https://dubaihousekeeping.com', 2014, 'شركة تنظيف منازل في دبي تقدم التنظيف العميق وتنظيف الانتقال وتنظيف الكنب بالبخار.', 'https://dubaihousekeeping.com/', 'تعمل دبي هاوس كيبينغ (غريس كويست لخدمات التنظيف) منذ 2014. وتقدم تنظيف المنازل والتدبير المنزلي والتنظيف العميق للشقق والفلل وتنظيف الانتقال والتنظيف بالبخار وتنظيف الكنب والمفروشات وتنظيف بيوت العطلات.', 'https://dubaihousekeeping.com/wp-content/uploads/2024/10/NewDb.png', null, 'مكتب 4201B، برج أسبن التجاري، شارع الشيخ زايد، دبي، ص.ب 236887', 'https://maps.app.goo.gl/EaD8HwnwrKy7b7ZE6', array['التنظيف العميق للشقق والفلل', 'تنظيف الانتقال', 'تنظيف الكنب والمفروشات', 'تنظيف بيوت العطلات وAirbnb', 'التنظيف بالبخار']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Grace Quest Cleaning Services (Dubai Housekeeping)'));
