select 'cleaning', 'Helen Maid Cleaning Services', 'Helen Maid Cleaning Services', 'دبي', 'المرقبات، ديرة', '+971559916741', 'https://helenmaid.com', null, 'شركة تنظيف في ديرة بدبي تقدم التنظيف العميق وتنظيف الكنب والسجاد والانتقال وتخدم الشارقة وعجمان.', 'https://helenmaid.com/', 'تقدم هيلين ميد خدمات التنظيف السكني مثل تنظيف المنازل والتنظيف العميق وتنظيف السجاد والكنب والمراتب والستائر وتنظيف الانتقال. كما تقدم التنظيف التجاري للمكاتب والمباني والمستودعات والمطاعم، وتخدم دبي والشارقة وعجمان.', 'https://helenmaid.com/wp-content/uploads/2022/10/Helen-Maid.jpeg', 'info@helenmaid.com', 'مكتب 82، الفهد بلازا، شارع الرقة، المرقبات، ديرة، دبي', 'https://maps.app.goo.gl/Yk15gzrnwGp3BRxDA', array['التنظيف العميق', 'تنظيف الكنب والمراتب والستائر', 'تنظيف السجاد', 'تنظيف الانتقال', 'تنظيف المكاتب والمباني']::text[], 'تعرض الشركة فريقاً يضم مديراً عاماً ومدير إدارة ومشرفاً وسبع عاملات تنظيف.', true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Helen Maid Cleaning Services'));
