select 'cleaning', 'باراديس لخدمات التنظيف', 'Paradise Cleaning Services', 'عجمان', 'الليوارة 1', '+971547825784', 'https://paradisecleaningmaids.com', null, 'شركة تنظيف في عجمان تقدم عاملات بدوام جزئي وتنظيف عميق وتنظيف الكنب والسجاد والمراتب.', 'https://paradisecleaningmaids.com/', 'تقدم باراديس لخدمات التنظيف عاملات بدوام جزئي وتنظيف المنازل والفلل والشقق والتنظيف العميق وتنظيف السجاد والكنب والمراتب، إلى جانب التنظيف التجاري. ومقرها عجمان وتخدم دبي والشارقة وأم القيوين.', 'https://paradisecleaningmaids.com/wp-content/uploads/2022/01/Paradise-Cleaning-Maids.jpeg', 'paradisecleaningmaids@gmail.com', 'مكتب 302، بناية البستان مدينة، الليوارة 1، عجمان', null, array['عاملات بدوام جزئي', 'التنظيف العميق', 'تنظيف الكنب والسجاد والمراتب', 'تنظيف الفلل والشقق', 'تنظيف المكاتب']::text[], 'يذكر الموقع أن لدى الشركة 36 عاملاً.', true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Paradise Cleaning Services'));
