select 'cleaning', 'Best Cleaning Company L.L.C', 'Best Cleaning Company L.L.C', 'رأس الخيمة', null, '+97172222995', 'https://www.bestcleaning.ae', 2005, 'شركة تنظيف في رأس الخيمة تأسست عام 2005 وتقدم التنظيف السكني والتجاري وتنظيف الواجهات.', 'https://www.bestcleaning.ae/contact-us/', 'تأسست بست كلينينغ عام 2005 ومقرها رأس الخيمة. وتقدم التنظيف السكني والتجاري والصناعي والتنظيف العميق وتنظيف الزجاج والواجهات الخارجية للأبراج، والتعقيم ومكافحة الحشرات، ولها أرقام تواصل في دبي وعجمان وأم القيوين.', 'https://www.bestcleaning.ae/wp-content/uploads/2021/01/l1.png', 'info@bestcleaning.ae', 'ص.ب 10995، رأس الخيمة', 'https://goo.gl/maps/QhFEHmVMxdtWHHhh8', array['التنظيف السكني', 'التنظيف العميق', 'تنظيف زجاج وواجهات الأبراج', 'تنظيف المستشفيات والمدارس', 'التعقيم ومكافحة الحشرات']::text[], null, true
