select 'interior', 'Al Manzool', 'Al Manzool', 'أبوظبي', null, '+971 2 644 5170', 'https://manzool.ae', 1991, 'شركة تصميم داخلي في أبوظبي تأسست عام 1991 للفلل والشقق والمكاتب والمجالس.', 'https://manzool.ae/', 'المنزول شركة تصميم داخلي في أبوظبي أسستها المعمارية إيمان عرفلي عام 1991. تخدم الفلل والشقق والمكاتب والمساحات التجارية، وتقدم تخطيط المساحات وتصميم الإضاءة والأثاث المخصص وتكامل المنزل الذكي.', 'https://manzool.ae/wp-content/uploads/2023/08/al_manzool_logo.png', 'info@manzool.ae', null, null, array['جلسات وطعام كبار الشخصيات', 'صالة كبار الشخصيات', 'جلسة عائلية', 'جلسة اللوبي', 'تصميم المجالس']::text[], 'أسستها المعمارية إيمان عرفلي، ويضم الفريق مصممين داخليين ومعماريين وحرفيين.', true
where not exists (select 1 from public.service_providers where category = 'interior' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Al Manzool'));
