select 'interior', 'النهج الحديث لمقاولات الديكور', 'Al Nahj Al Hadeeth Decor', 'الشارقة', 'الصناعية 7', '+971 50 404 2756', 'https://nmc-decor.ae', null, 'شركة مقاولات ديكور داخلي وخارجي في الشارقة تقدم التصميم الداخلي وأعمال الخشب والأسقف والمطابخ.', 'https://nmc-decor.ae/%D9%85%D9%82%D8%A7%D9%88%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D8%AF%D9%8A%D9%83%D9%88%D8%B1-2', 'النهج الحديث شركة لمقاولات الديكور الداخلي والخارجي مقرها الشارقة وتخدم عملاء في أنحاء الإمارات. تشمل خدماتها التصميم الداخلي وتصميم الحمامات والأرضيات الخشبية والرخامية والأسقف وخزائن المطابخ.', 'https://nmc-decor.ae/wp-content/uploads/2022/08/Logo-main.png', 'info@nmc-decor.ae', 'الصناعية 7، خلف السفير مول، الشارقة', null, array['مقاولات الديكور', 'التصميم الداخلي', 'خزائن المطابخ', 'الأسقف الخشبية والألمنيوم', 'الأرضيات الخشبية والرخامية']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'interior' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Al Nahj Al Hadeeth Decor'));
