select 'maintenance', 'We Will Fix It Services LLC', 'We Will Fix It Services LLC', 'دبي', 'Dubai Investments Park', '+971 4 807 3295', 'https://www.wewillfixit.com', 2008, 'شركة صيانة منزلية في دبي منذ 2008 تقدم خدمات التكييف والكهرباء والسباكة والدهان وعقود الصيانة.', 'https://www.wewillfixit.com/contact-us/', 'أسس الشركة في دبي عام 2008 المغتربان البريطانيان كولن توماس ودان غارنر. تقدم صيانة وإصلاح المكيفات واستبدالها، وتنظيف الدكتات، والكهرباء والسباكة والدهان وأعمال الصيانة العامة وخدمات الطوارئ، إضافة إلى عقود صيانة سنوية سكنية وتجارية.', 'https://www.wewillfixit.com/wp-content/uploads/2023/01/WWFI-Full-Logo-Purple-Neon-Yellow-Text.png', 'info@wewillfixit.com', 'المرحلة 1، قطعة 194، مجمع دبي للاستثمار، دبي', null, array['صيانة وإصلاح المكيفات', 'تنظيف الدكتات والكويلات', 'خدمات الطوارئ', 'تنظيف خزانات المياه', 'عقود الصيانة السنوية السكنية والتجارية']::text[], 'أسسها كولن توماس ودان غارنر، ويعمل بها فنيون مرخصون ومؤمَّن عليهم.', true
where not exists (select 1 from public.service_providers where category = 'maintenance' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('We Will Fix It Services LLC'));
