select 'maintenance', 'Octopus MEP Technical Services LLC (Octopus Home Maintenance)', 'Octopus MEP Technical Services LLC (Octopus Home Maintenance)', 'دبي', 'Dubai Investments Park', '800 3993', 'https://octopus.ae', 2013, 'شركة صيانة وتجديد منازل في دبي تقدم خدمات التكييف والسباكة والكهرباء وتنقية المياه.', 'https://octopus.ae/about-us/', 'أوكتوبوس شركة تأسست عام 2013 وتقدم خدمات تحسين وصيانة المنازل في المجمعات السكنية بدبي. تشمل خدماتها صيانة المكيفات وتركيبها، والسباكة وسخانات المياه، والكهرباء، وتنظيف الخزانات، وتجديد الفلل والشقق والمطابخ والحمامات، وعقود الصيانة السنوية. تعرض شعار بلدية دبي ضمن ترخيصها.', 'https://octopus.ae/wp-content/uploads/2025/08/logo.svg', null, 'مستودع 20، مستودعات أرينكو، مجمع دبي للاستثمار 1، دبي', 'https://maps.app.goo.gl/FKXDGmws6fNjZZv38', array['صيانة وتركيب المكيفات', 'تجديد الفلل والشقق', 'تجديد المطابخ والحمامات', 'تنظيف خزانات المياه', 'عقود الصيانة السنوية']::text[], 'يقودها زوبين فيروزي (الرئيس التنفيذي والشريك الإداري) مع فريق للصيانة والتصميم وخدمة العملاء.', true
where not exists (select 1 from public.service_providers where category = 'maintenance' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Octopus MEP Technical Services LLC (Octopus Home Maintenance)'));
