select 'maintenance', 'Al Shirawi Facilities Management LLC', 'Al Shirawi Facilities Management LLC', 'دبي', null, '+971 4 333 7644', 'https://www.alshirawifm.com', null, 'شركة إدارة مرافق متكاملة في دبي ضمن مجموعة الشيراوي تقدم صيانة الأنظمة الكهروميكانيكية والمباني.', 'https://www.alshirawifm.com/', 'الشيراوي لإدارة المرافق جزء من مجموعة شركات الشيراوي، وتقدم إدارة مرافق متكاملة تشمل الهندسة والصيانة الكهروميكانيكية وصيانة هيكل المبنى وإدارة الطاقة والتنظيف. يذكر موقع المجموعة أنها بدأت مقاولاً ميكانيكياً عام 1974، بينما يذكر موقع الشركة سنة تأسيس 2010.', 'https://www.alshirawifm.com/images/asfmlogomob.png', 'bd@alshirawifm.com', 'ص.ب 33539، دبي، الإمارات', null, array['إدارة المرافق المتكاملة', 'الهندسة والصيانة', 'استشارات وخدمات الطاقة', 'الأمن والحلول الذكية', 'التنظيف']::text[], 'يعمل بها نحو 1500 موظف ولديها أكثر من 350 عقداً نشطاً.', true
where not exists (select 1 from public.service_providers where category = 'maintenance' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Shirawi Facilities Management LLC'));
