select 'property_mgmt', 'Metropolitan Premium Properties', 'Metropolitan Premium Properties', 'دبي', 'مدينة دبي للإنترنت', '+971 4 428 6151', 'https://metropolitan.realestate', 2008, 'شركة عقارية في دبي تقدم إدارة العقارات للملاك من التسعير والتسويق إلى تحصيل الإيجار وإيجاري.', 'https://metropolitan.realestate/services/property-management/', 'تأسست الشركة عام 2008 وتقدم خدمة إدارة العقارات بنسبة من الإيجار الشهري أو رسم شهري ثابت. تشمل الخدمة تحديد الإيجار والإصلاحات والتنظيف والتسويق وفحص المستأجرين وتسجيل إيجاري وتحصيل الإيجار والتجديد ومعاينات الدخول والخروج، مع تطبيق للملاك للتقارير المالية.', null, null, 'الطوابق 36-38، برج السلام تيكوم، مدينة دبي للإنترنت، دبي', null, array['تحديد قيمة الإيجار', 'فحص المستأجرين', 'تسجيل إيجاري', 'تحصيل الإيجار', 'تطبيق للملاك']::text[], 'مديرة إدارة العقارات: آيكو دوريمخان؛ ويذكر الموقع 250 وكيلًا.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Metropolitan Premium Properties'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'تنامي العقارية', 'Tanami Properties', 'دبي', 'دبي مارينا', '+971 4 248 3400', 'https://www.tanamiproperties.ae', null, 'شركة في دبي تدير أبراجًا سكنية وتجارية في دبي والشارقة وعجمان نيابة عن الملاك.', 'https://www.tanamiproperties.ae/Property-Management.aspx', 'تقدم تنامي العقارية خدمات إدارة العقارات تشمل فحص المستأجرين والتسويق والتحصيل والصيانة والتجديد وفق أنظمة الإيجار والتقارير الدورية للملاك. تذكر الشركة أنها تدير أكثر من 900 وحدة في 4 أبراج بدبي و3 بالشارقة وبرج في عجمان.', 'https://www.tanamiproperties.ae/Content/images/logo.webp', 'info@tanamiproperties.ae', 'مكتب 3405، مارينا بلازا، شارع المرسى، دبي مارينا، دبي', null, array['فحص المستأجرين', 'تحصيل الإيجار', 'تنسيق الصيانة', 'تجديد العقود', 'تقارير دورية للملاك']::text[], 'يضم فريق تأجير يشمل وسطاء مرخصين من دائرة الأراضي في دبي.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Tanami Properties'));
