select 'property_mgmt', 'Deyaar Property Management', 'Deyaar Property Management', 'دبي', 'البرشاء 1', '+971 4 384 0950', 'https://www.deyaar.ae', null, 'ذراع إدارة العقارات لدى ديار تدير مشاريع سكنية وتجارية ومختلطة في الإمارات.', 'https://www.deyaar.ae/en/pm/', 'تقدم ديار لإدارة العقارات خدمات إدارة للمشاريع السكنية والتجارية والمختلطة في الإمارات، ولها فروع في أبوظبي والعين والشارقة والفجيرة ورأس الخيمة. تذكر الشركة أنها تدير أكثر من 12,000 وحدة وأكثر من 700 مشروع لأكثر من 400 مالك.', 'https://www.deyaar.ae/wp-content/uploads/2023/07/Logo_black.svg', 'contactus@deyaar.ae', 'الطابق الخامس، مبنى ديار، البرشاء 1، دبي', null, array['برج العامري - دبي', 'برج الفجيرة - الفجيرة', 'برج السادة - الشارقة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Deyaar Property Management'));
