select 'property_mgmt', 'شركة السوم العقارية ذ.م.م', 'Alsoum Real Estate', 'الشارقة', 'السور', '+971 6 544 5569', 'https://www.alsoum.com', 2005, 'شركة عقارية في الشارقة تقدم إدارة العقارات والصيانة وإدارة الحسابات والخدمات القانونية الإيجارية.', 'https://www.alsoum.com/ar/', 'تأسست شركة السوم العقارية عام 2005 في الشارقة. تقدم إدارة العقارات والصيانة والسلامة والخدمات القانونية لنزاعات الإيجار وإدارة الحسابات والإشراف على المشاريع والوساطة والتقييم العقاري.', 'https://www.alsoum.com/ar/assets/img/img/logo.webp', 'info@alsoum.com', 'الشارقة – السور – بناء AMD – مكتب رقم M02 وM03 وM04', null, array['إدارة العقارات', 'الصيانة والسلامة', 'الخدمات القانونية لنزاعات الإيجار', 'إدارة الحسابات', 'التقييم العقاري']::text[], 'لديها أقسام مختصة للتأجير والحسابات والشؤون القانونية والتقييم والصيانة.', true
