select 'engineering', 'Al Gurg Consultants', 'Al Gurg Consultants', 'دبي', null, null, null, 1969, 'مكتب استشارات هندسية ومعمارية مقره دبي، تأسس عام 1969.', 'https://www.zawya.com/en/press-release/companies-news/azizi-developments-partners-with-uaes-al-gurg-consultants-for-venice-r1dokbld', 'شركة استشارات هندسية ومعمارية مقرها الرئيسي في دبي، تأسست عام 1969. في مايو 2024 تعاقدت معها شركة عزيزي للتطوير العقاري على التصميم التفصيلي لثمانية أبراج سكنية في مشروع عزيزي فينيسيا بدبي ساوث.', null, null, null, null, array['التصميم التفصيلي لثمانية أبراج سكنية في مشروع عزيزي فينيسيا - دبي ساوث']::text[], null, true
