select 'legal', 'Al Safar & Partners Advocates and Legal Consultants', 'Al Safar & Partners Advocates and Legal Consultants', 'دبي', 'داون تاون (المدينة القديمة)', '800 529937', 'https://dubailawyers.ae', null, 'مكتب محاماة في دبي يتولى التقاضي العقاري وعقود البيع والإيجار والعناية الواجبة قبل الشراء.', 'https://dubailawyers.ae/real-estate-law', 'مكتب محاماة واستشارات قانونية في دبي يقدم خدمات التقاضي العقاري والبيع والشراء والتأجير واتفاقيات التطوير والمشاريع المشتركة وصياغة العقود ومراجعتها. ويذكر المكتب أنه ترافع في أكثر من 2600 قضية عقارية منذ 2010، ويقدم المساعدة في نزاعات الإيجار قبل التقاضي وبعده، إلى جانب ممارسات أخرى كتحصيل الديون والتحكيم.', null, 'alsafar@alsafarpartners.com', 'مكاتب ساحة 401A، المبنى D، المدينة القديمة، داون تاون، بالقرب من فندق القصر، دبي', null, array['التقاضي في النزاعات العقارية', 'مراجعة اتفاقيات البيع والشراء والتفاوض عليها', 'العناية الواجبة قبل شراء العقار', 'نزاعات الإيجار', 'اتفاقيات التطوير والمشاريع المشتركة']::text[], 'أسسه الشريك المؤسس مهدي الصفر، وتديره الشريكة الإدارية كافيثا س. بانيكر.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Safar & Partners Advocates and Legal Consultants'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'legal', 'Al Kabban & Associates', 'Al Kabban & Associates', 'دبي', 'الخليج التجاري', '+971 4 453 9090', 'https://alkabban.com', 1993, 'مكتب محاماة في دبي تأسس عام 1993 ويقدم خدمات قانون العقارات والتقاضي.', 'https://alkabban.com/real-estate-law/', 'مكتب محاماة في دبي تأسس عام 1993 لتقديم خدمات قانونية في مجال العقار والاستثمار. يغطي قسمه العقاري صفقات البيع والشراء وعقود الإيجار السكنية والتجارية ودعم المطورين والتمويل العقاري وقانون الملكية المشتركة وتسجيل سندات الملكية والنزاعات بين المؤجر والمستأجر.', 'https://alkabban.com/wp-content/uploads/2026/04/Al-Kabban-Logo-01.png', 'info@alkabban.com', 'مكتب رقم 2906، برج بريزم، الخليج التجاري، دبي، ص.ب 4790', null, array['صفقات بيع وشراء العقارات', 'عقود الإيجار السكنية والتجارية', 'دعم المطورين العقاريين', 'قانون الملكية المشتركة (الاستراتا)', 'نزاعات المؤجر والمستأجر']::text[], 'أسسه الدكتور رياض القبان (المدير والمؤسس)، ومن فريقه الشريك الأول سيف المطوع.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Kabban & Associates'));
