select 'legal', 'Majed Bin Weqaish and Shoaib Al Awadhi Advocates and Legal Consultants L.L.C', 'Majed Bin Weqaish and Shoaib Al Awadhi Advocates and Legal Consultants L.L.C', 'أبوظبي', 'جزيرة الريم', '+971 2 582 0010', 'https://www.mswlaw.ae', null, 'مكتب محاماة مقره أبوظبي يتولى التقاضي في النزاعات العقارية بأنواعها.', 'https://www.mswlaw.ae/Real-Estate-Litigation.html', 'مكتب محاماة واستشارات قانونية مقره الرئيسي برج أداكس في جزيرة الريم بأبوظبي. يتولى قسم التقاضي العقاري النزاعات العقارية بأنواعها للمطورين والبائعين والمشترين والمقرضين والمستثمرين.', 'https://www.mswlaw.ae/assets/images/resources/logo-light-1-1.png', 'info@mswlaw.ae', 'برج أداكس، الطابق 17، مكاتب 1711-1712، جزيرة الريم، أبوظبي', 'https://www.google.com/maps/place/Addax+Office+Tower/@24.498933,54.403117,16z/data=!4m5!3m4!1s0x0:0x3b49e7595dafcef7!8m2!3d24.4989329!4d54.4031167?hl=en', array['التقاضي في النزاعات العقارية', 'تمثيل المطورين والمشترين والمستثمرين']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Majed Bin Weqaish and Shoaib Al Awadhi Advocates and Legal Consultants L.L.C'));
