select 'residency', 'Uniwide Advisors FZCO', 'Uniwide Advisors FZCO', 'دبي', null, '+97145625400', 'https://www.uniwide.com', null, 'مزوّد خدمات شركات دولية مقره الرئيسي دبي، يقدم تأسيس الشركات وخدمات المندوب والإقامة.', 'https://www.uniwide.com/about/', 'تقدم يونيوايد استشارات تسجيل الشركات وتشغيلها في أكثر من 30 ولاية قضائية، ومكتبها الرئيسي في دبي. تشمل خدماتها في الإمارات تأسيس الشركات في البر الرئيسي والمناطق الحرة والأوفشور، وخدمات المندوب، والإقامة، وفتح الحسابات المصرفية والضرائب. لها مكاتب أيضاً في سيشل ولندن وريغا.', 'https://www.uniwide.com/wp-content/uploads/2026/04/uniwide-logo-white.svg', null, null, null, array['تأسيس الشركات في البر الرئيسي والمناطق الحرة', 'خدمات المندوب (PRO)', 'تأشيرات الإقامة والهوية الإماراتية', 'فتح الحسابات المصرفية', 'تسجيل ضريبة الشركات والقيمة المضافة']::text[], 'فريق دولي من متخصصي تسجيل الشركات والمحامين والمحاسبين بخبرة تزيد على 15 عاماً.', true
where not exists (select 1 from public.service_providers where category = 'residency' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Uniwide Advisors FZCO'));
